---@class PayActivityConfig
local PayActivityConfig = T(Global, "PayActivityConfig")
---@type ActivityConfigData[]
local SettingList = {}
---@type PayActivityRoundsConfigData[]
local RoundsSettingList = {}
---@type PayActivityLoginUIData[]
local LogingUISetting = {}

local function date2timestamp(date)
    if not date or date == "#" then
        return -1
    end
    date = StringUtil.split(date, ",", nil, true)
    return DateUtil.date2BeiJingTime({
        year = tonumber(date[1]),
        month = tonumber(date[2]),
        day = tonumber(date[3]),
        hour = tonumber(date[4]) or 0,
        min = tonumber(date[5]) or 0,
        sec = tonumber(date[6]) or 0
    })
end

local function getSeconds(date)
    if not date or date == "#" then
        return -1
    end
    date = StringUtil.split(date, ",", nil, true)
    return (date[1] or 0) * 86400 + (date[2] or 0) * 3600 + (date[3] or 0) * 60 + (date[4] or 0)
end

---@private
function PayActivityConfig:init()
    self.config = FileUtil.getGameConfigFromJson("pay_activity/PayActivity.json")
    self.config.mainButton = self.config.mainButton or {}
    for _, cfg in pairs(self.config.mainButton) do
        cfg.startDate = date2timestamp(cfg.startDate)
        cfg.endDate = date2timestamp(cfg.endDate)
    end
    local config = FileUtil.getGameConfigFromCsv("pay_activity/PayActivityList.csv")
    for _, item in pairs(config or {}) do
        ---@class PayActivityConfigData
        local data = {
            id = tonumber(item.id),
            class = item.class,
            startDate = date2timestamp(item.startDate),
            endDate = date2timestamp(item.endDate),
            updateTime = getSeconds(item.updateTime),
            loginShowUI = item.loginShowUI,
            tabImage = item.tabImage,
            tabName = item.tabName,
            panelName = item.panelName,
            introduce = item.introduce,
            activityUIName = item.activityUIName,
            order = tonumber(item.order) or 1,
            hideTimeUI=tonumber(item.hideTimeUI) or 0
        }
        SettingList[data.id] = data
    end

    if isClient then
        config = FileUtil.getGameConfigFromCsv("pay_activity/PayActivityLoginUI.csv")
        for _, item in pairs(config or {}) do
            ---@class PayActivityLoginUIData
            local data = {
                activityId = tonumber(item.activityId),
                layout = item.layout,
            }
            data.params = {
                item.param1,
                item.param2,
                item.param3,
                item.param4,
            }
            LogingUISetting[data.activityId] = data
        end

        Plugins.LoadPlugin("red_dot")
        local activityTag = {}
        for _, cfg in pairs(SettingList) do
            table.insert(activityTag, "pay_activity:" .. cfg.id)
        end
        Plugins.CallTargetPluginFunc("red_dot", "registerProfile", {
            ["pay_activity"] = activityTag,
        })
    end
    self:loadActivityRoundCfg()
    --print("------------------>>>PayActivityConfig:init ")
    --LogUtil.pv(SettingList)
end

function PayActivityConfig:loadActivityRoundCfg()
    local config = FileUtil.getGameConfigFromCsv("pay_activity/PayActivityRounds.csv")
    self.totalTime=0
    self.roundStartTime=0
    self.roundsCfg=config
    if not config then
        return
    end
    for _, item in pairs(config or {}) do
        ---@class PayActivityRoundsConfigData
        local data = {
            id = tonumber(item.n_id),
            activityId = tonumber(item.n_activityId),
            order = tonumber(item.n_sortId) or 1,
            roundsTime = date2timestamp(item.s_roundsTime),
            continueTime = getSeconds(item.s_continueTime),
        }
        table.insert(RoundsSettingList,data)
        self.totalTime=self.totalTime+data.continueTime
    end
    table.sort(RoundsSettingList,function (a,b)
        return a.order<b.order
    end)
    if RoundsSettingList[1]~=nil then
        self.roundStartTime=RoundsSettingList[1].roundsTime
    end
    print("--------------- loadActivityRoundCfg:",self.roundStartTime,self.totalTime/(3600*24))
    --LogUtil.pv(RoundsSettingList)
    self:checkResetRoundTime(true)
    if isClient then
        LuaTimer:scheduleTimer(function()
            self:checkResetRoundTime(false)
        end, 1000)
    end
end

function PayActivityConfig:checkResetRoundTime(isInit)
    if self.roundStartTime > 0 then
        local curTime = os.time()
        local diff=curTime-self.roundStartTime
        if diff >= self.totalTime or isInit then
            self.roundStartTime=self.roundStartTime+self.totalTime*math.max(0,math.floor(diff/self.totalTime))
            print(">>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>checkResetRoundTime,",diff,self.totalTime,math.max(0,math.floor(diff/self.totalTime)))
            local startTime=self.roundStartTime
            for i = 1, #RoundsSettingList do
                local cfg=RoundsSettingList[i]
                local payActivityListCfg=SettingList[cfg.activityId]
                if payActivityListCfg then
                    payActivityListCfg.startDate=startTime
                    payActivityListCfg.endDate=startTime+cfg.continueTime
                end
                startTime=startTime+cfg.continueTime
            end
        end
        --print("checkResetRoundTime:")
        --LogUtil.pv(SettingList)
    end
end

---@return ActivityConfigData[]
function PayActivityConfig:getAllCfgs()
    return SettingList
end

---@return ActivityConfigData
function PayActivityConfig:getCfgById(id)
    return SettingList[id]
end

---@return PayActivityLoginUIData
function PayActivityConfig:getLoginUICfgById(activityId)
    return LogingUISetting[activityId]
end

PayActivityConfig:init()

return PayActivityConfig